# frozen_string_literal: true

module ActiveRecordULID
  # Rails casts a model's default attributes once and shares them, so a ULID
  # generated by the type would be the same for every record. A :ulid attribute
  # without an explicit default gets one that generates per record instead.
  module AttributeDefault
    def attribute(name, type = nil, **options)
      type = resolve_type_name(type, **options.except(:default)) if type == :ulid
      if type.is_a?(Type) && type.generates_default? && !options.key?(:default)
        options[:default] = -> { type.generate }
      end

      super
    end
  end
end
